import{_ as l,W as n,s as d,u as g,I as s,ah as p,w as e,Z as i,A as o}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const f=JSON.parse('{"title":"如何使用 Tig 浏览 Git 日志 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Tig 浏览 Git 日志 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何使用 Tig 浏览 Git 日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Tig 浏览 Git 日志 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190627 How to use Tig to browse Git logs","title":"如何使用 Tig 浏览 Git 日志","tag":"201907"},"relativePath":"201907/20190627 How to use Tig to browse Git logs.md","filePath":"[post].md"}'),r={name:"201907/20190627 How to use Tig to browse Git logs.md"};function u(h,t,c,b,m,v){const a=n("Link");return g(),d("div",null,[t[30]||(t[30]=s("h1",{id:"如何使用-tig-浏览-git-日志",tabindex:"-1"},[e("如何使用 Tig 浏览 Git 日志 "),s("a",{class:"header-anchor",href:"#如何使用-tig-浏览-git-日志","aria-label":"Permalink to 如何使用 Tig 浏览 Git 日志"},"​")],-1)),t[31]||(t[31]=s("blockquote",null,[s("p",null,"Tig 可不仅仅是 Git 的文本界面。以下是它如何增强你的日常工作流程。")],-1)),t[32]||(t[32]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/201907/07/111847v1zx3qk5qqhklyjp.png",alt:""})],-1)),s("p",null,[t[1]||(t[1]=e("如果你使用 Git 作为你的版本控制系统，你可能已经让自己接受了 Git 是一个复杂的野兽的事实。它是一个很棒的工具，但浏览 Git 仓库可能很麻烦。因此像 ")),i(a,{href:"https://jonas.github.io/tig/"},{default:o(()=>t[0]||(t[0]=[e("Tig")])),_:1}),t[2]||(t[2]=e(" 这样的工具出现了。"))]),s("p",null,[t[4]||(t[4]=e("来自 ")),i(a,{href:"http://manpages.ubuntu.com/manpages/bionic/man1/tig.1.html"},{default:o(()=>t[3]||(t[3]=[e("Tig 手册页")])),_:1}),t[5]||(t[5]=e("："))]),t[33]||(t[33]=p('<blockquote><p>Tig 是 <code>git</code>(1) 的基于 ncurses 的文本界面。它主要用作 Git 仓库浏览器，但也有助于在块级别暂存提交更改，并作为各种 Git 命令的输出分页器。</p></blockquote><p>这基本上意味着 Tig 提供了一个可以在终端中运行的基于文本的用户界面。Tig 可以让你轻松浏览你的 Git 日志，但它可以做的远不止让你从最后的提交跳到前一个提交。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig.jpg" alt="Tig screenshot" title="Tig screenshot"></p><p>这篇快速入门的 Tig 中的许多例子都是直接从其出色的手册页中拿出来的。我强烈建议你阅读它以了解更多信息。</p><h3 id="安装-tig" tabindex="-1">安装 Tig <a class="header-anchor" href="#安装-tig" aria-label="Permalink to 安装 Tig">​</a></h3><ul><li>Fedora 和 RHEL： <code>sudo dnf install tig</code></li><li>Ubuntu 和 Debian： <code>sudo apt install tig</code></li><li>MacOS： <code>：brew install tig</code></li></ul>',6)),s("p",null,[t[7]||(t[7]=e("有关更多方式，请参阅官方")),i(a,{href:"https://jonas.github.io/tig/INSTALL.html"},{default:o(()=>t[6]||(t[6]=[e("安装说明")])),_:1}),t[8]||(t[8]=e("。"))]),t[34]||(t[34]=p('<h3 id="浏览当前分支中的提交" tabindex="-1">浏览当前分支中的提交 <a class="header-anchor" href="#浏览当前分支中的提交" aria-label="Permalink to 浏览当前分支中的提交">​</a></h3><p>如果要浏览分支中的最新提交，请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig</span></span></code></pre></div><p>就是这样。这个三字符命令将启动一个浏览器，你可以在其中浏览当前分支中的提交。你可以将其视为 <code>git log</code> 的封装器。</p><p>要浏览这些输出，可以使用向上和向下箭头键从一个提交移动到另一个提交。按回车键将会垂直分割窗口，右侧包含所选提交的内容。你可以继续在左侧的提交历史记录中上下浏览，你的更改将显示在右侧。使用 <code>k</code> 和 <code>j</code> 可以逐行上下浏览，<code>-</code> 和空格键可以在右侧上下翻页。使用 <code>q</code> 退出右侧窗格。</p><p>搜索 <code>tig</code> 输出也很简单。使用 <code>/</code> （向前）或 <code>?</code> （向后）在左右窗格中搜索。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-search.png" alt="Searching Tig" title="Searching Tig"></p><p>这些就足以让你浏览你的提交信息了。这里有很多的键绑定，但单击 <code>h</code> 将显示“帮助”菜单，你可以在其中发现其导航和命令选项。你还可以使用 <code>/</code> 和 <code>?</code> 来搜索“帮助”菜单。使用 <code>q</code> 退出帮助。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-help.png" alt="Tig Help" title="Tig Help"></p><h3 id="浏览单个文件的修改" tabindex="-1">浏览单个文件的修改 <a class="header-anchor" href="#浏览单个文件的修改" aria-label="Permalink to 浏览单个文件的修改">​</a></h3><p>由于 Tig 是 <code>git log</code> 的封装器，它可以方便地接受可以传递给 <code>git log</code> 的相同参数。例如，要浏览单个文件的提交历史记录，请输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig README.md</span></span></code></pre></div><p>将其与被封装的 Git 命令的输出进行比较，以便更清楚地了解 Tig 如何增强输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log README.md</span></span></code></pre></div><p>要在原始 Git 输出中包含补丁，你可以添加 <code>-p</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log -p README.md</span></span></code></pre></div><p>如果要将提交范围缩小到特定日期范围，请尝试以下操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig --after=&quot;2017-01-01&quot; --before=&quot;2018-05-16&quot; -- README.md</span></span></code></pre></div><p>再一次，你可以将其与原始的 Git 版本进行比较：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git log --after=&quot;2017-01-01&quot; --before=&quot;2018-05-16&quot; -- README.md</span></span></code></pre></div><h3 id="浏览谁更改了文件" tabindex="-1">浏览谁更改了文件 <a class="header-anchor" href="#浏览谁更改了文件" aria-label="Permalink to 浏览谁更改了文件">​</a></h3><p>有时你想知道谁对文件进行了更改以及原因。命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig blame README.md</span></span></code></pre></div><p>器本质上是 <code>git blame</code> 的封装。正如你所期望的那样，它允许你查看谁是编辑指定行的最后一人，它还允许你查看到引入该行的提交。这有点像 vim 的 <code>vim-fugitive</code> 插件提供的 <code>:Gblame</code> 命令。</p><h3 id="浏览你的暂存区" tabindex="-1">浏览你的暂存区 <a class="header-anchor" href="#浏览你的暂存区" aria-label="Permalink to 浏览你的暂存区">​</a></h3><p>如果你像我一样，你可能会在你的暂存区做了许多修改。你很容易忘记它们。你可以通过以下方式查看暂存处中的最新项目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git stash show -p stash@{0}</span></span></code></pre></div><p>你可以通过以下方式找到第二个最新项目：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git stash show -p stash@{1}</span></span></code></pre></div><p>以此类推。如果你在需要它们时调用这些命令，那么你会有比我更清晰的记忆。</p><p>与上面的 Git 命令一样，Tig 可以通过简单的调用轻松增强你的 Git 输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig stash</span></span></code></pre></div><p>尝试在有暂存的仓库中执行此命令。你将能够浏览<em>并搜索</em>你的暂存项，快速浏览你的那些修改。</p><h3 id="浏览你的引用" tabindex="-1">浏览你的引用 <a class="header-anchor" href="#浏览你的引用" aria-label="Permalink to 浏览你的引用">​</a></h3><p>Git ref 是指你提交的东西的哈希值。这包括文件和分支。使用 <code>tig refs</code> 命令可以浏览所有的 ref 并深入查看特定提交。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig refs</span></span></code></pre></div><p>完成后，使用 <code>q</code> 回到前面的菜单。</p><h3 id="浏览-git-状态" tabindex="-1">浏览 git 状态 <a class="header-anchor" href="#浏览-git-状态" aria-label="Permalink to 浏览 git 状态">​</a></h3><p>如果要查看哪些文件已被暂存，哪些文件未被跟踪，请使用 <code>tig status</code>，它是 <code>git status</code> 的封装。</p><p><img src="https://opensource.com/sites/default/files/uploads/tig-status.png" alt="Tig status" title="Tig status"></p><h3 id="浏览-git-grep" tabindex="-1">浏览 git grep <a class="header-anchor" href="#浏览-git-grep" aria-label="Permalink to 浏览 git grep">​</a></h3><p>你可以使用 <code>grep</code> 命令在文本文件中搜索表达式。命令 <code>tig grep</code> 允许你浏览 <code>git grep</code> 的输出。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tig grep -i foo lib/Bar</span></span></code></pre></div><p>它会让你浏览 <code>lib/Bar</code> 目录中以大小写敏感的方式搜索 <code>foo</code> 的输出。</p><h3 id="通过标准输入管道输出给-tig" tabindex="-1">通过标准输入管道输出给 Tig <a class="header-anchor" href="#通过标准输入管道输出给-tig" aria-label="Permalink to 通过标准输入管道输出给 Tig">​</a></h3><p>如果要将提交 ID 列表传递给 Tig，那么必须使用 <code>--stdin</code> 标志，以便 <code>tig show</code> 从标准输入读取。否则，<code>tig show</code> 会在没有输入的情况下启动（出现空白屏幕）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git rev-list --author=olaf HEAD | tig show --stdin</span></span></code></pre></div><h3 id="添加自定义绑定" tabindex="-1">添加自定义绑定 <a class="header-anchor" href="#添加自定义绑定" aria-label="Permalink to 添加自定义绑定">​</a></h3>',48)),s("p",null,[t[10]||(t[10]=e("你可以使用 ")),i(a,{href:"https://en.wikipedia.org/wiki/Run_commands"},{default:o(()=>t[9]||(t[9]=[e("rc")])),_:1}),t[11]||(t[11]=e(" 文件自定义 Tig。以下是如何根据自己的喜好添加一些有用的自定义键绑定的示例。"))]),t[35]||(t[35]=p(`<p>在主目录中创建一个名为 <code>.tigrc</code> 的文件。在你喜欢的编辑器中打开 <code>~/.tigrc</code> 并添加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 应用选定的暂存内容</span></span>
<span class="line"><span>bind stash a !?git stash apply %(stash)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 丢弃选定的暂存内容</span></span>
<span class="line"><span>bind stash x !?git stash drop %(stash)</span></span></code></pre></div><p>如上所述，运行 <code>tig stash</code> 以浏览你的暂存。但是，通过这些绑定，你可以按 <code>a</code> 将暂存中的项目应用到仓库，并按 <code>x</code> 从暂存中删除项目。请记住，你要在浏览暂存<em>列表</em>时，才能执行这些命令。如果你正在浏览暂存<em>项</em>，请输入 <code>q</code> 退出该视图，然后按 <code>a</code> 或 <code>x</code> 以获得所需效果。</p>`,3)),s("p",null,[t[13]||(t[13]=e("有关更多信息，你可以阅读有关 ")),i(a,{href:"https://github.com/jonas/tig/wiki/Bindings"},{default:o(()=>t[12]||(t[12]=[e("Tig 键绑定")])),_:1}),t[14]||(t[14]=e("。"))]),t[36]||(t[36]=s("h3",{id:"总结",tabindex:"-1"},[e("总结 "),s("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to 总结"},"​")],-1)),t[37]||(t[37]=s("p",null,"我希望这有助于演示 Tig 如何增强你的日常工作流程。Tig 可以做更强大的事情（比如暂存代码行），但这超出了这篇介绍性文章的范围。这里有足够的让你置身于危险的信息，但还有更多值得探索的地方。",-1)),t[38]||(t[38]=s("hr",null,null,-1)),s("p",null,[t[16]||(t[16]=e("via: ")),i(a,{href:"https://opensource.com/article/19/6/what-tig"},{default:o(()=>t[15]||(t[15]=[e("https://opensource.com/article/19/6/what-tig")])),_:1})]),s("p",null,[t[21]||(t[21]=e("作者：")),i(a,{href:"https://opensource.com/users/oalders/users/mbbroberg/users/marcobravo"},{default:o(()=>t[17]||(t[17]=[e("Olaf Alders")])),_:1}),t[22]||(t[22]=e(" 选题：")),i(a,{href:"https://github.com/lujun9972"},{default:o(()=>t[18]||(t[18]=[e("lujun9972")])),_:1}),t[23]||(t[23]=e(" 译者：")),i(a,{href:"https://github.com/geekpi"},{default:o(()=>t[19]||(t[19]=[e("geekpi")])),_:1}),t[24]||(t[24]=e(" 校对：")),i(a,{href:"https://github.com/wxy"},{default:o(()=>t[20]||(t[20]=[e("wxy")])),_:1})]),s("p",null,[t[27]||(t[27]=e("本文由 ")),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>t[25]||(t[25]=[e("LCTT")])),_:1}),t[28]||(t[28]=e(" 原创编译，")),i(a,{href:"https://linux.cn/"},{default:o(()=>t[26]||(t[26]=[e("Linux中国")])),_:1}),t[29]||(t[29]=e(" 荣誉推出"))])])}const C=l(r,[["render",u]]);export{f as __pageData,C as default};
